from pathlib import Path
import gzip,json,urllib.request,urllib.parse,datetime,hashlib
O=Path(__file__).parent
names=['Шеметово (Московская область)','Сынково','Кудиново (Богородский городской округ)','Ямкино','Федино (Воскресенский район)','Растуново','Часцы (посёлок)','Хлюпино (деревня)','Волоколамск','Пушкино','Звенигород','Лобня','Сергиев Посад','Шатура','Электроугли','Красногорск','Бужаниново (село)','Пирогово (Мытищи)','Шарапово (городской округ Чехов)','Масловский (Зарайский район)','Поповка (сельское поселение Сафоновское)','Поповка (сельское поселение Ульянинское)','Кирпичного завода (городской округ Серпухов)','Клязьминское Водохранилище','Поминово (Московская область)','Щёкино (Волоколамский район)','Светлый (Ногинский район)','Ткацкой Фабрики','Завода Стройполимер','Поречье (Звенигород)']
u='https://ru.wikipedia.org/w/api.php?'+urllib.parse.urlencode(dict(action='query',titles='|'.join(names),prop='revisions|pageprops|coordinates',rvprop='ids|content|timestamp',rvslots='main',format='json',redirects=1,colimit='max'))
with urllib.request.urlopen(urllib.request.Request(u,headers={'User-Agent':'SettlementResearch/1.0'}),timeout=40)as r:b=r.read(9000000);status=r.status
f=O/'own_wikipedia_batch3.json.gz';f.write_bytes(gzip.compress(b));j=json.loads(b);rows=[dict(title=p['title'],missing='missing'in p,pageid=p.get('pageid'),revid=p.get('revisions',[{}])[0].get('revid'),point=p.get('coordinates'))for p in j.get('query',{}).get('pages',{}).values()];(O/'fetch_batch3_receipt.json').write_text(json.dumps(dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),request_url=u,normal_TLS=True,status=status,sha256=hashlib.sha256(f.read_bytes()).hexdigest(),pages=rows),ensure_ascii=False,indent=2));print(json.dumps(rows,ensure_ascii=False))
